import ast, sys, pathlib
# Scan backend-B for Python 3.9+ syntax that would fail on 3.8
root = pathlib.Path("backend-B")
issues = []
for f in sorted(root.rglob("*.py")):
    if "__pycache__" in str(f): continue
    try:
        src = f.read_text(encoding="utf-8")
        ast.parse(src, filename=str(f), feature_version=(3, 8))
    except SyntaxError as e:
        issues.append((str(f), e.lineno, e.msg))
    # manual checks
    for i, line in enumerate(src.splitlines(), 1):
        if "removeprefix" in line or "removesuffix" in line:
            issues.append((str(f), i, "removeprefix/removesuffix (3.9+)"))
        if "zoneinfo" in line:
            issues.append((str(f), i, "zoneinfo (3.9+)"))
        if re_match := __import__("re").search(r"(?<!:)\|\s*(?!\|)", line):
            # dict | dict merge or type union — heuristic; check outside annotations
            stripped = line.lstrip()
            if not stripped.startswith(("#", "def", "class")) and "|" in line:
                # Only flag `dict |`-style merges used as expressions
                if re_match and not (line.strip().startswith('"') or line.strip().startswith("'")):
                    pass
print("3.8 syntax issues:")
for it in issues: print(it)
if not issues: print("(none)")
EOF

